import {createState,advance,call,decide,CALLS,DURATION} from './model.js';
const $=id=>document.getElementById(id);let state=createState(),paused=false,quiet=false,sound=false,started=false,last=0,pendingChoice='',priorPause=false;
const time=s=>String(Math.floor(s/60)).padStart(2,'0')+':'+String(Math.floor(s%60)).padStart(2,'0');
function speak(text){if(sound&&'speechSynthesis'in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='de-DE';u.rate=.9;speechSynthesis.speak(u);}}
function logInto(target){const box=$(target);box.replaceChildren();for(const e of state.log){const li=document.createElement('li'),b=document.createElement('b');b.textContent=time(e.at)+' · '+e.who;li.append(b,document.createTextNode(e.text));box.append(li);}if(target==='log')box.scrollTop=box.scrollHeight;}
function clip(scene){if($('motion').checked)return;const src={begleitung:'begleitung',kontakt:'kontakt',befehl:'begleitung',sinkflug:'sinkflug'}[scene];if(!src)return;const v=$('cinema');$('stage').classList.remove('video-ready');v.src='assets/'+src+'.mp4';v.onloadeddata=()=>{$('stage').classList.add('video-ready');if(!paused&&!state.ended)v.play().catch(()=>$('stage').classList.remove('video-ready'));};v.onerror=()=>$('stage').classList.remove('video-ready');v.load();}
function render(events=[]){for(const e of events){if(e.scene){clip(e.scene);$('stage').dataset.scene=e.scene;$('phase').textContent={begleitung:'Begleitung',kontakt:'Kontaktversuch',befehl:'Keine Freigabe',sinkflug:'Sinkflug',nahsicht:'Die Ungewissheit bleibt',entscheidung:'Entscheidungspunkt'}[e.scene];$('sceneTitle').textContent=$('phase').textContent;}$('subtitle').textContent=e.text;speak(e.text);}
 $('clock').textContent=time(DURATION-state.elapsed);if(state.elapsed>=85)$('order').textContent='Ausdrücklicher Befehl: Nicht abschiessen. Lauterbach übermittelt die Ablehnung aus der politischen Führung.';
 document.querySelectorAll('[data-call]').forEach(b=>b.disabled=paused||state.called.includes(b.dataset.call)||state.elapsed>=DURATION);logInto('log');
 if(state.elapsed>=DURATION){paused=true;$('cinema').pause();$('stage').classList.add('paused');$('pause').disabled=true;$('step').disabled=true;$('callStatus').textContent='Die Spielzeit ist angehalten. Triff deine Entscheidung oder gehe mit offener Entscheidung zur Reflexion.';}
}
function setPause(value){paused=value;if(value)$('cinema').pause();else if($('cinema').src&&!$('cinema').ended&&!$('motion').checked)$('cinema').play().catch(()=>{});$('stage').classList.toggle('paused',value);$('pause').textContent=value?'Fortsetzen':'Pause';$('step').disabled=value;if(value&&'speechSynthesis'in window)speechSynthesis.cancel();render();}
$('calls').replaceChildren();for(const [id,c] of Object.entries(CALLS)){const b=document.createElement('button');b.dataset.call=id;b.textContent=c.label;b.onclick=()=>{if(paused)return;if(call(state,id)){$('subtitle').textContent=c.own;speak(c.own);$('callStatus').textContent='Gesendet. Du wartest auf eine Antwort …';render();}};$('calls').append(b);}
$('start').onclick=()=>{quiet=document.querySelector('input[name=mode]:checked').value==='quiet';sound=$('sound').checked;$('intro').hidden=true;$('game').hidden=false;$('stage').classList.toggle('still',$('motion').checked);$('step').hidden=!quiet;started=true;last=performance.now();render(advance(state,0));window.scrollTo(0,0);};
$('pause').onclick=()=>setPause(!paused);$('step').onclick=()=>{if(!paused)render(advance(state,15));};
setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,1);last=now;if(started&&!quiet&&!paused&&!state.ended)render(advance(state,dt));},250);
document.addEventListener('visibilitychange',()=>{if(document.hidden&&started&&!state.ended)setPause(true);});
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{pendingChoice=b.dataset.choice;priorPause=paused;setPause(true);$('confirmTitle').textContent=pendingChoice==='schiessen'?'Du willst den Abschuss entscheiden.':'Du willst nicht schiessen.';$('confirm').showModal();});
$('confirmNo').onclick=()=>{$('confirm').close();setPause(priorPause);};$('confirm').addEventListener('cancel',()=>setPause(priorPause));$('confirmYes').onclick=()=>{$('confirm').close();finish(pendingChoice);};$('exit').onclick=()=>finish('offen');
function finish(choice){if(!decide(state,choice))return;paused=true;$('cinema').pause();if('speechSynthesis'in window)speechSynthesis.cancel();$('game').hidden=true;$('debrief').hidden=false;$('resultTitle').textContent={schiessen:'Du entscheidest dich für den Abschuss.',nicht:'Du entscheidest dich, nicht zu schiessen.',offen:'Du lässt die Entscheidung offen.'}[choice];$('resultText').textContent={schiessen:'Damit entscheidest du über das Leben der Menschen an Bord, ohne eine Abschusserlaubnis zu haben. Die Simulation zeigt keinen Treffer und behauptet nicht, damit sei die Rettung des Stadions bewiesen.',nicht:'Du tötest die Menschen an Bord nicht durch einen Abschuss. Die Gefahr für das Stadion bleibt in deiner Wahrnehmung bestehen. Die Simulation behauptet weder einen Einschlag noch eine spätere Rettung.',offen:'Auch deine Unentschiedenheit lässt sich untersuchen. Welche Information oder welche Unterstützung hätte dir gefehlt? Daraus folgt keine Bewertung deiner Persönlichkeit.'}[choice];$('decisionKnowledge').textContent='Dein Entscheidungszeitpunkt: '+time(state.elapsed)+'. '+(state.elapsed>=85?'Du hattest den ausdrücklichen Nicht-Abschussbefehl gehört.':'Du hast vor der ausdrücklichen Rückmeldung entschieden; eine Freigabe lag auch vorher nicht vor.')+(state.elapsed>=120?' Der simulierte Sinkflug hatte begonnen.':' Der simulierte Sinkflug hatte noch nicht begonnen.');logInto('reviewLog');window.scrollTo(0,0);save();}
function save(){try{localStorage.setItem('terror-cockpit-reflection-v1',JSON.stringify({choice:state.choice,elapsed:state.elapsed,log:state.log,reason:$('reason').value,question:$('question').value}));$('saved').textContent='Reflexion auf diesem Gerät gespeichert.';}catch{$('saved').textContent='Speichern ist hier nicht möglich. Lade dein Protokoll herunter.';}}
for(const id of ['reason','question'])$(id).oninput=save;
try{const saved=JSON.parse(localStorage.getItem('terror-cockpit-reflection-v1')||'null');if(saved){$('reason').value=saved.reason||'';$('question').value=saved.question||'';}}catch{}
$('download').onclick=()=>{const text='TERROR · Cockpit-Simulation\nFunkdialog und Ablauf didaktisch erfunden.\n\n'+$('resultTitle').textContent+'\n'+state.log.map(e=>time(e.at)+' '+e.who+': '+e.text).join('\n\n')+'\n\nBegründung:\n'+$('reason').value+'\n\nFrage an Koch:\n'+$('question').value;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='terror-cockpit-reflexion.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('restart').onclick=()=>location.reload();$('motion').checked=matchMedia('(prefers-reduced-motion: reduce)').matches;
